-- 1060: Powder metal calculators -- compaction pressing and belt sintering as real database calculators.
--
-- GENERATED by scripts/generate-powder-metal-calculators-migration.ts from
-- src/modules/bom-items/costing/powder-metal/calculators/powder-metal-calculators.json.
-- Do not edit by hand: change the spec and regenerate.
--
-- ROOT CAUSE
--
-- Powder Metal was staged (reference data 2026-PowderMetal, 16 HR Rates machines, 7 powders with their compaction curves)
-- but had no cost engine: its two catalog operations had no calculator, and a part whose Process is Powder Metal was not
-- costed. These are the calculators of its route: compaction pressing and belt sintering compute their operations; the
-- compaction pressure, the press force and the fill height are helpers no operation maps to.
--
-- This migration creates one global calculator per spec entry (inputs are the
-- values the cost engine seeds, each shown with its source in the calculation
-- trace; calculated fields are the formulas the engine evaluates, it holds
-- none) and links every Powder Metal catalog operation it computes to its
-- calculator in process_calculator_mappings.
--
-- Requires migration 804 (calculators.retired_at).
-- Self-contained, idempotent, post-checked.

BEGIN;

-- Powder Metal - Powder
DO $calc$
DECLARE v_id UUID;
BEGIN
  SELECT id INTO v_id FROM public.calculators WHERE name = $q$Powder Metal - Powder$q$ AND user_id IS NULL AND retired_at IS NULL;
  IF v_id IS NULL THEN
    INSERT INTO public.calculators (user_id, name, calc_category, calculator_type, is_template, is_public, is_global, description)
    VALUES (NULL, $q$Powder Metal - Powder$q$, 'process', 'single', false, true, true, $q$The powder a part takes: the part's volume at its green density, bought at the powder's price, over the material utilization (defaultUtilization: the powder lost in feeding, filling and handling).$q$)
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.calculators SET calc_category = 'process', description = $q$The powder a part takes: the part's volume at its green density, bought at the powder's price, over the material utilization (defaultUtilization: the powder lost in feeding, filling and handling).$q$, updated_at = now() WHERE id = v_id;
  END IF;

  DELETE FROM public.calculator_fields WHERE calculator_id = v_id;
  INSERT INTO public.calculator_fields
    (calculator_id, field_name, display_label, field_type, unit, data_source, source_table, source_field, default_value, display_order, is_required)
  VALUES
    (v_id, $q$Part Volume$q$, $q$Part Volume (mm³)$q$, $q$number$q$, $q$mm³$q$, NULL, NULL, NULL, NULL, 1, true),
    (v_id, $q$Green Density$q$, $q$Green Density (kg/m³)$q$, $q$number$q$, $q$kg/m³$q$, NULL, NULL, NULL, NULL, 2, true),
    (v_id, $q$Powder Price$q$, $q$Powder Price (USD/kg)$q$, $q$number$q$, $q$USD/kg$q$, NULL, NULL, NULL, NULL, 3, true),
    (v_id, $q$Utilization$q$, $q$Utilization$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 4, true),
    (v_id, $q$Part Mass$q$, $q$Part Mass (kg)$q$, $q$calculated$q$, $q$kg$q$, NULL, NULL, NULL, $q${Part Volume} * {Green Density} * 1e-9$q$, 5, false),
    (v_id, $q$Powder Mass$q$, $q$Powder Mass (kg)$q$, $q$calculated$q$, $q$kg$q$, NULL, NULL, NULL, $q${Part Mass} / {Utilization}$q$, 6, false),
    (v_id, $q$Material Cost$q$, $q$Material Cost (USD)$q$, $q$calculated$q$, $q$USD$q$, NULL, NULL, NULL, $q${Powder Mass} * {Powder Price}$q$, 7, false);
END
$calc$;

-- Powder Metal - Compaction pressure
