    (v_id, $q$Parts per Metre$q$, $q$Parts per Metre$q$, $q$calculated$q$, NULL, NULL, NULL, NULL, $q$min({Parts Across} * 1000 / ({Part Length} + {Part Spacing}), {Max Belt Load} / {Part Mass})$q$, 15, false),
