-- Post-check: every calculator exists once, with all its fields, linked to every operation it computes.
DO $post$
DECLARE bad TEXT;
BEGIN
  SELECT string_agg(e.name, ', ') INTO bad
  FROM (VALUES
    ($q$Powder Metal - Powder$q$, 7, 0),
    ($q$Powder Metal - Compaction pressure$q$, 6, 0),
    ($q$Powder Metal - Press force$q$, 3, 0),
    ($q$Powder Metal - Fill height$q$, 5, 0),
    ($q$Powder Metal - Compaction$q$, 3, 1),
    ($q$Powder Metal - Sintering$q$, 16, 1)
  ) AS e(name, field_count, mapping_count)
  LEFT JOIN public.calculators c ON c.name = e.name AND c.user_id IS NULL AND c.retired_at IS NULL
  WHERE c.id IS NULL
     OR (SELECT count(*) FROM public.calculator_fields f WHERE f.calculator_id = c.id) <> e.field_count
     OR (SELECT count(*) FROM public.process_calculator_mappings m WHERE m.calculator_id = c.id AND m.process_group = $q$Powder Metal$q$ AND (m.is_active OR m.machine_class IS NULL)) <> e.mapping_count;
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'migration 1060: calculators incomplete: %', bad;
  END IF;
END
$post$;

COMMIT;
